"""Read-only complete dt/16 report, known kinetic clock and load-stop partition."""
import json,os,runpy,time
from pathlib import Path
os.environ.update(OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',MPLBACKEND='Agg')
ROOT=Path('/Users/b09501028/Downloads/bem2d.jl/Tatva-BEM');OUT=ROOT/'bem/outputs/fem-dt16-window-analysis-20261031';OUT.mkdir(exist_ok=False);os.environ['MPLCONFIGDIR']=str(OUT/'mpl-cache')
import numpy as np
import matplotlib.pyplot as plt
TOOLS=ROOT/'bem/tools';C=runpy.run_path(str(TOOLS/'compare_extended_fem_windows.py'));DIGEST=C['DIGEST'];EVENT=C['BASE']['EVENT'];COMPARE=C['BASE']['BASE']['COMPARE']['compare_saved_p1_fields'];begun=time.perf_counter()
base=ROOT/'bem/outputs/fem-window-postrupture-study-20261030/window';study=ROOT/'bem/outputs/fem-window-finer-study-20261030';fine=study/'window';path=study/'comparison.json';comparison=json.loads(path.read_text());summary,manifest,files=C['verified_extension'](fine)
assert comparison['status']=='completed_conditional_fem_extended_time_comparison'and not comparison['finer_local_one_percent_diagnostic']
assert all(DIGEST(p)==v for p,v in comparison['frozen_inputs_sha256'].items())
frozen={str(p):DIGEST(p)for p in [Path(__file__),path,study/'release.json',fine/'summary.json',fine/'extension_manifest.json',base/'summary.json',base/'factor4.npz']}
records={r['factor']:r for r in json.loads((base/'summary.json').read_text())['records']if r['factor']==4};records.update({r['factor']:r for r in summary['records']});first,last=summary['first_shear_step'],summary['last_shear_step'];data={f:C['load_branch'](base if f==4 else fine,r,first,last)for f,r in records.items()};ref=data[16];t,y=ref['time'],ref['y'];start=summary['physical_shear_interval_s'][0]
assert all(np.array_equal(a['time'],t)and np.array_equal(a['y'],y)for a in data.values())
cut=min(comparison['loading_hold_first_fine_endpoint_s'][str(f)]for f in [8,16]);idx=int(np.searchsorted(t,cut));assert 0<idx<len(t);fraction=(cut-t[idx-1])/(t[idx]-t[idx-1]);partitions={}
for field in ref['fields']:
 partitions[field]={}
 for label,left in [('before_first_loading_hold',True),('after_first_loading_hold',False)]:
  args=[]
  for f in [16,8]:
   v=data[f]['fields'][field];at_cut=(1-fraction)*v[idx-1]+fraction*v[idx]
   clock=np.r_[t[:idx],cut]if left else np.r_[cut,t[idx:]]
   values=np.vstack((v[:idx],at_cut))if left else np.vstack((at_cut,v[idx:]))
   args.append((clock,y,values))
  partitions[field][label]=COMPARE(*args)
 total=sum(v['error_squared_space_time_integral']for v in partitions[field].values());original=comparison['contact_errors_against_dt_over_16']['8'][field]['error_squared_space_time_integral'];assert abs(total-original)<=1e-12*max(original,1)
 partitions[field]['fraction_squared_error_before_first_hold']=partitions[field]['before_first_loading_hold']['error_squared_space_time_integral']/total if total else 0.
clock={f:start+np.arange(1,len(a['scalar'])+1)*records[f]['dt_s']for f,a in data.items()};kinetic_clock={f:c+records[f]['dt_s']/2 for f,c in clock.items()};kinetic={str(f):EVENT['waveform_error'](kinetic_clock[16],ref['scalar'][:,9],kinetic_clock[f],data[f]['scalar'][:,9])for f in [4,8]}
fig,axes=plt.subplots(2,2,figsize=(11,7),constrained_layout=True);dy=np.diff(y)
def norm(v):return np.sum(dy/3*(v[:,:-1]**2+v[:,:-1]*v[:,1:]+v[:,1:]**2),axis=1)
for f,a in data.items():
 ids=np.unique(np.r_[np.arange(0,len(clock[f]),max(1,len(clock[f])//5000)),len(clock[f])-1]);label=f'dt/{f}';axes[0,0].plot(clock[f][ids]*1000,a['scalar'][ids,5],lw=.9,label=label);axes[1,1].plot(y,a['fields']['pressure'][-1],lw=.9,label=label)
 if f!=16:
  for ax,name in [(axes[0,1],'pressure'),(axes[1,0],'elastic_shear')]:ax.plot(t*1000,np.sqrt(norm(a['fields'][name]-ref['fields'][name])/norm(ref['fields'][name]))*100,label=label+' vs dt/16')
for ax in [axes[0,1],axes[1,0]]:ax.axvline(cut*1000,color='gray',ls=':',lw=1,label='First dt/8,16 hold')
axes[0,0].set(title='Peak cumulative slip: full scalar window',ylabel='Cumulative slip (mm)',xlabel='Actual shear time (ms)');axes[0,1].set(title='Whole-interface pressure error',ylabel='Saved-time P1 L2 difference (%)',xlabel='Actual shear time (ms)');axes[1,0].set(title='Whole-interface signed shear error',ylabel='Saved-time P1 L2 difference (%)',xlabel='Actual shear time (ms)');axes[1,1].set(title=f'Last shared saved time {t[-1]*1000:.6f} ms',ylabel='Pressure (MPa)',xlabel='Contact coordinate y (mm)')
for ax in axes.ravel():ax.grid(alpha=.2);ax.legend(fontsize=8)
fig.savefig(OUT/'dt16-window-comparison.png',dpi=160);plt.close(fig)
assert all(DIGEST(p)==v for p,v in frozen.items())
result=dict(status='completed_complete_conditional_dt16_read_only_report',original_comparison=comparison,extension_summary=summary,owner_release=json.loads((study/'release.json').read_text()),known_half_step_kinetic_errors_against_dt16=kinetic,load_stop_partition=partitions,load_stop_partition_cut_s=cut,partition_scope='Diagnostic additive partition of the same complete saved P1 fields, keeping all spatial endpoints and interpolating only inside a saved temporal cell. Original full-window acceptance gate unchanged.',scalar_scope='All native rows retained; P1 metric within common temporal overlap, without downsampling, fitted shift or extrapolation.',source_and_input_sha256=frozen,all_completed_extension_receipts_and_chunks_freshly_verified=True,total_analysis_seconds=time.perf_counter()-begun)
(OUT/'summary.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n');print(json.dumps(dict(partitions={k:{'before':v['before_first_loading_hold']['relative_space_time_p1_l2'],'after':v['after_first_loading_hold']['relative_space_time_p1_l2'],'before_squared_error_fraction':v['fraction_squared_error_before_first_hold']}for k,v in partitions.items()},known_half_step_kinetic={f:v['absolute_signal']['relative_time_p1_l2']for f,v in kinetic.items()})),flush=True)
